import sys
from concurrent.futures import ThreadPoolExecutor

import pytest

WORKERS: int = 4
"""Thread pool size used by sum_squares; must be >= 1."""


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int]) -> int:
    """Return the sum of x*x for every x in xs, computing the squares
    in parallel with a ThreadPoolExecutor of WORKERS threads.

    The result is exactly the same for every worker count (integer
    addition is exact, so the order in which squares finish cannot
    matter). An empty list gives 0. The input list is not modified.
    """
    with ThreadPoolExecutor(max_workers=WORKERS) as pool:
        return sum(pool.map(square, xs))


def _set_workers(monkeypatch: pytest.MonkeyPatch, n: int) -> None:
    monkeypatch.setattr(sys.modules[__name__], "WORKERS", n)


def test_empty() -> None:
    assert sum_squares([]) == 0


def test_single() -> None:
    assert sum_squares([7]) == 49
    assert sum_squares([-7]) == 49
    assert sum_squares([0]) == 0


def test_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_negatives_and_mixed() -> None:
    assert sum_squares([-1, -2, -3]) == 14
    assert sum_squares([-3, 4]) == 25


def test_big_ints() -> None:
    big = 10**12
    assert sum_squares([big, -big]) == 2 * big * big


def test_does_not_mutate_input() -> None:
    xs = [3, -1, 2]
    sum_squares(xs)
    assert xs == [3, -1, 2]


@pytest.mark.parametrize("workers", [1, 2, 3, 4, 8, 64])
def test_same_result_at_every_worker_count(
    monkeypatch: pytest.MonkeyPatch, workers: int
) -> None:
    _set_workers(monkeypatch, workers)
    xs = [(i * 37) % 101 - 50 for i in range(500)]
    expected = sum(x * x for x in xs)
    assert sum_squares(xs) == expected


@pytest.mark.parametrize("workers", [1, 2, 16])
def test_more_workers_than_items(
    monkeypatch: pytest.MonkeyPatch, workers: int
) -> None:
    _set_workers(monkeypatch, workers)
    assert sum_squares([2]) == 4
    assert sum_squares([1, 2]) == 5
    assert sum_squares([]) == 0


@pytest.mark.parametrize("workers", [1, 5])
def test_order_independent(monkeypatch: pytest.MonkeyPatch, workers: int) -> None:
    _set_workers(monkeypatch, workers)
    xs = list(range(-20, 21))
    assert sum_squares(xs) == sum_squares(list(reversed(xs)))


def test_matches_sequential_with_default_workers() -> None:
    xs = list(range(1000))
    assert sum_squares(xs) == sum(square(x) for x in xs)


def test_uses_thread_pool(monkeypatch: pytest.MonkeyPatch) -> None:
    created: list[int] = []

    class Spy(ThreadPoolExecutor):
        def __init__(self, max_workers: int | None = None) -> None:
            created.append(-1 if max_workers is None else max_workers)
            super().__init__(max_workers)

    monkeypatch.setattr(sys.modules[__name__], "ThreadPoolExecutor", Spy)
    _set_workers(monkeypatch, 3)
    assert sum_squares([1, 2, 3, 4]) == 30
    assert created == [3]
